        SIMDUInt8.bitwiseOr(
            SIMDUInt8.saturatingSubtracting(prev2, SIMDUInt8.repeating(0x60)),
            SIMDUInt8.saturatingSubtracting(prev3, SIMDUInt8.repeating(0x70))
        )
